#define UNICODE_RANGE_COUNT \
    ((u32)(sizeof(UNICODE_RANGES) / sizeof(UNICODE_RANGES[0])))

/* Binary search over the sorted, non-overlapping ranges above.
 * Returns 0 (no flags) for any codepoint not covered by a range,
 * which includes the entire unassigned bulk of the codespace and
 * any cp > 0x10FFFF a caller might (incorrectly) pass in. */
static inline u8 unicode_cpt_flags(u32 cp) {
    u32 lo = 0, hi = UNICODE_RANGE_COUNT;
    while (lo < hi) {
        u32 mid = lo + (hi - lo) / 2;
        if (cp < UNICODE_RANGES[mid].lo) {
            hi = mid;
        } else if (cp > UNICODE_RANGES[mid].hi) {
            lo = mid + 1;
        } else {
            return UNICODE_RANGES[mid].flags;
        }
    }
    return 0;
}

